+// ---- stopping policy ----
+#include <cstdio>
+#include <vector>
+#include <algorithm>
+
+namespace {
+
+const int kResultCount = 50;          // requested result count k of the workload
+const float kTargetProbability = 0.9f; // success probability of the function-table test
+
+// Function table F(theta, s): probability that, in one hash table, a point at
+// angle theta from the query lies in a bucket whose probing score is at most s.
+// A point is then found by the L tables with probability 1 - (1 - F)^L.
+// Columns (one score value each) are read lazily, in file order, as probing
+// reaches them; for every angle row we keep the first column passing the test.
+class FunctionTable {
+public:
+	FunctionTable() : file_(NULL), attempted_(false), rows_(0), cols_(0), loaded_(0), tables_(0) {}
+
+	bool attempted() const { return attempted_; }
+	bool ready() const { return rows_ > 0; }
+	int tables() const { return tables_; }
+
+	void open(const char* path, int tables)
+	{
+		attempted_ = true;
+		tables_ = tables;
+		if (path == NULL || tables <= 0) return;
+		file_ = std::fopen(path, "rb");
+		if (file_ == NULL) return;
+		float bounds[4];
+		int shape[3];
+		if (std::fread(bounds, sizeof(float), 4, file_) != 4 ||
+			std::fread(shape, sizeof(int), 3, file_) != 3 ||
+			shape[0] != 4 || shape[1] <= 0 || shape[2] <= 0 || shape[2] > 30000) {
+			std::fclose(file_);
+			file_ = NULL;
+			return;
+		}
+		rows_ = shape[1];
+		cols_ = shape[2];
+		theta_min_ = bounds[0];
+		theta_step_ = (bounds[1] - bounds[0]) / rows_;
+		score_min_ = bounds[2];
+		score_step_ = (bounds[3] - bounds[2]) / cols_;
+		first_col_.assign(rows_, -1);
+		irregular_.assign(rows_, 0);
+		passes_.reserve((size_t)rows_ * cols_);
+		// Per-table probability at which 1 - (1 - F)^L reaches the target;
+		// entries this close to it are decided with the exact expression.
+		double p = 1.0 - std::pow(1.0 - (double)kTargetProbability, 1.0 / tables);
+		split_ = (float)p;
+		band_lo_ = (float)(p - 1e-4);
+		band_hi_ = (float)(p + 1e-4);
+	}
+
+	// Index convention of the authors' loader: step = range / count, truncated.
+	int row(float theta) const { return clamp((int)((theta - theta_min_) / theta_step_), rows_); }
+	int col(float score) const { return clamp((int)((score - score_min_) / score_step_), cols_); }
+
+	// 1 - (1 - F(row, col))^L >= target.
+	bool passes(int r, int c)
+	{
+		if (c >= loaded_ && !load_through(c)) return false;
+		if (irregular_[r]) return passes_[(size_t)c * rows_ + r] != 0;
+		return first_col_[r] >= 0 && c >= first_col_[r];
+	}
+
+private:
+	static int clamp(int i, int n) { return i < 0 ? 0 : (i >= n ? n - 1 : i); }
+
+	bool load_through(int c)
+	{
+		if (file_ == NULL) return false;
+		int target = std::min(cols_, c + 17);
+		int count = target - loaded_;
+		chunk_.resize((size_t)count * rows_);
+		if (std::fread(&chunk_[0], sizeof(float), chunk_.size(), file_) != chunk_.size()) {
+			std::fclose(file_);
+			file_ = NULL;
+			return false;
+		}
+		ok_.resize(rows_);
+		int* ok = &ok_[0];
+		int* first = &first_col_[0];
+		int* irregular = &irregular_[0];
+		const float split = split_, lo = band_lo_, hi = band_hi_;
+		for (int k = 0; k < count; ++k, ++loaded_) {
+			const float* column = &chunk_[(size_t)k * rows_];
+			int near_split = 0;
+			for (int r = 0; r < rows_; ++r) {
+				float p = column[r];
+				ok[r] = p >= split;
+				near_split |= (p > lo) & (p < hi);
+			}
+			if (near_split) {
+				for (int r = 0; r < rows_; ++r) {
+					float p = column[r];
+					if (p > lo && p < hi) ok[r] = 1.0f - std::pow(1.0f - p, (float)tables_) >= kTargetProbability;
+				}
+			}
+			// A row that passes and later fails is answered from the stored flags.
+			const int current = loaded_;
+			for (int r = 0; r < rows_; ++r) {
+				int f = first[r];
+				irregular[r] |= (ok[r] == 0) & (f >= 0);
+				first[r] = (ok[r] != 0 && f < 0) ? current : f;
+			}
+			size_t base = passes_.size();
+			passes_.resize(base + rows_);
+			unsigned char* dst = &passes_[base];
+			for (int r = 0; r < rows_; ++r) dst[r] = (unsigned char)ok[r];
+		}
+		if (loaded_ == cols_) {
+			std::fclose(file_);
+			file_ = NULL;
+		}
+		return c < loaded_;
+	}
+
+	FILE* file_;
+	bool attempted_;
+	int rows_, cols_, loaded_, tables_;
+	float theta_min_, theta_step_, score_min_, score_step_;
+	float split_, band_lo_, band_hi_;
+	std::vector<float> chunk_;
+	std::vector<int> first_col_;
+	std::vector<int> irregular_;
+	std::vector<int> ok_;
+	std::vector<unsigned char> passes_;
+};
+
+FunctionTable g_table;
+
+// True once k live results reach the partition's maximum inner product: no
+// point still unseen in this partition (or in any later, lower-norm one) can
+// enter the reported top-k, so further probes cannot change it.
+bool g_partition_settled = false;
+
+// Angle row of the threshold kth / (c * M), cached while its inputs repeat.
+float g_cached_kth = 0.0f, g_cached_ratio = 0.0f, g_cached_max = 0.0f;
+int g_cached_row = -1;
+
+bool topk_reaches(const float* scores, size_t count, float bound)
+{
+	if (scores == NULL || count < (size_t)kResultCount) return false;
+	int hits = 0;
+	for (size_t i = 0; i < count; ++i) hits += scores[i] >= bound;
+	return hits >= kResultCount;
+}
+
+} // namespace
+
 bool should_stop(const SearchState& search_state)
 {
-	return search_state.candidates_verified >= search_state.candidate_budget;
+	if (search_state.candidates_verified >= search_state.candidate_budget) return true;
+	if (!g_table.attempted()) g_table.open(search_state.policy_resource, search_state.hash_tables);
+
+	int probes = search_state.probes_performed;
+	if (probes <= 1 || (probes & (probes - 1)) == 0)
+		g_partition_settled = topk_reaches(search_state.top_scores, search_state.top_score_count,
+			search_state.maximum_inner_product * 1.000001f);
+	if (g_partition_settled) return true;
+
+	// Function-table test: stop once a point whose inner product reaches
+	// kth / c would have been found with the target probability.
+	if (!g_table.ready() || search_state.hash_tables != g_table.tables()) return false;
+	float kth = search_state.kth_score;
+	if (kth <= 0.0f) return false;
+	if (kth != g_cached_kth || search_state.approximation_ratio != g_cached_ratio ||
+		search_state.maximum_inner_product != g_cached_max) {
+		g_cached_kth = kth;
+		g_cached_ratio = search_state.approximation_ratio;
+		g_cached_max = search_state.maximum_inner_product;
+		float x = kth / (search_state.approximation_ratio * search_state.maximum_inner_product);
+		g_cached_row = x >= 1.0f ? -1 : g_table.row(std::acos(x));
+	}
+	if (g_cached_row < 0) return true;
+	return g_table.passes(g_cached_row, g_table.col(search_state.frontier_score));
 }

+
 void saveAndShow(float c, int k, std::string& dataset, std::vector<resOutput>& res)
 {
 	time_t now = time(0);
